package task2;

import java.util.*; public class StockFeedAdapter implements StockProvider { private final LegacyStockFeed feed; public StockFeedAdapter(LegacyStockFeed feed) { if(feed==null) throw new IllegalArgumentException(); this.feed=feed; } private Map<String,String> parse(String raw) { Map<String,String> result=new HashMap<>(); for(String part:raw.split(";")){ String[] pair=part.split("=",2); if(pair.length==2) result.put(pair[0].trim(),pair[1].trim()); } return result; } public double getMarketPrice(String ticker) { Map<String,String> p=parse(feed.fetchRawTickerPacket(ticker)); return (Double.parseDouble(p.getOrDefault("BID","0"))+Double.parseDouble(p.getOrDefault("ASK","0")))/2; } public String getStatus(String ticker) { return parse(feed.fetchRawTickerPacket(ticker)).getOrDefault("STATUS","UNAVAILABLE"); } }
